/* ---------- SRC-30.3 · STORM GARDEN V3 (the three-cloud band: vertical loom, rain is the percussion, farm the jellies) ---------- */
(() => {
// three low-poly storm clouds (Lance's picks, 10KB each) — inlined so the
// scene is self-contained online AND in the offline show build
const SG3_CLOUDS = ['', '', ''];
// palette extracted from ship_in_clouds.glb — indigo sky, ember left, violet right
const SG3 = {
  sky: 0x070512, cloudDark: 0x16122c,
  warm: 0xff8a3d, warmDeep: 0xb0522a,
  vio: 0xa06cff, vioDeep: 0x5b3fbf,
  ctr: 0xd9c8ff, cream: 0xffe0b8
};
reg({
  id: 'SRC-30.3', family: 'SRC-30', ver: 4,
  title: 'Storm Garden V3', tech: 'VERTICAL LOOM / WEATHER BAND',
  music: {
    bpm: 88, root: 48, mode: 'aeolian', chordBars: 2,
    chords: [
      [0, 15, 19, 20, 22],  // Cm7b13
      [0, 7, 8, 15, 26],    // Cm9b13 — the G/Ab blur
      [0, 10, 15, 17, 26],  // Cm11
      [0, 7, 10, 15, 22]    // Cm7
    ],
    chordNames: ['Cm7♭13', 'Cm9♭13', 'Cm11', 'Cm7']
  },
  fx: { bloom: 0.5 },
  tags: ['THREE-CLOUD BAND', 'PULSES CLIMB THE COLUMNS', 'RAIN = PERCUSSION', 'FARM THE JELLIES'],
  desc: 'Three storm clouds hang over a dark garden, each one a different member of the band. The EARTH cloud on the left rains warm log-drum plucks on eighths; the SKY cloud on the right rains violet bells on sixteenths; the THUNDER cloud in the middle only speaks when you charge it — and answers with a full-frame strike. Every note is telegraphed: a pulse of light climbs the rain column and the note lands the instant it reaches the cloud — a metronome you can see, one beat ahead. And the garden remembers: rain long enough on one patch and a jelly plant sprouts there, adding its voice to the drone. Keep farming and the garden fills with six swaying, glowing jellies — your chord, grown from weather.',
  interact: 'LEFT hand reach = rain on the left (earth) cloud, RIGHT hand = the right (sky) cloud — each hand is its own drummer, and where you rain composes the groove. RAISE BOTH HANDS HIGH to charge the thunder cloud: it swells, the tension rises, and the strike lands exactly on the next half-bar — lean into it. Rain long enough in one place and a jelly plant sprouts (on the bar, with a rolled arpeggio). Six plants max; they live while you keep the garden alive.',
  sound: 'Three layers on a C-minor pedal (the blur chords — the root never moves, the color does). DRONE: sub + soft triangle bed + one voice per grown jelly plant, panned to where it grew. QUANTIZED: earth rain = plucks on 8ths (arp ch4), sky rain = bells on 16ths (bells ch5), strikes on the half-bar (thunder on texture ch6 — rack your real thunder samples there; C1-region trigger). REACTIVE: charge = rising storm rumble that tracks your hold, sprouts roll low-to-high, and there is NO percussion in a garden nobody rains on. Silence is what makes thunder work.',
  init(P) {
    const s = P.state = {
      pres: 0, eL: 0, eR: 0, pL: 0, pR: 0, vel: 0,
      rainL: 0, rainR: 0, charge: 0, charging: false,
      strikePending: false, strikeAt: 0, strikeCool: 0,
      flashA: 0, bolt: null, boltT: 0,
      moist: [0, 0, 0],
      plants: [], newPlants: [], drops: [],
      landL: 0, landR: 0, idleT: 0
    };
    if (typeof THREE === 'undefined') { s.noGL = true; return; }
    if (P._three) { try { P._three.renderer.dispose(); } catch (e) {} }
    const T3 = {}; P._three = T3;
    const r = new THREE.WebGLRenderer({ antialias: false });
    r.setSize(P.w, P.h, false);
    r.setClearColor(SG3.sky, 1);
    T3.renderer = r;
    const A2 = P.w / Math.max(1, P.h);
    T3.A = A2;
    const sc = new THREE.Scene();
    const cam = new THREE.OrthographicCamera(-A2, A2, 1, -1, 0.1, 10);
    cam.position.z = 2;
    T3.scene = sc; T3.cam = cam;

    // ---- glow quad shader (cloud under-edges, plant bells) ----
    const glowMat = (col) => new THREE.ShaderMaterial({
      transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
      uniforms: { uCol: { value: new THREE.Color(col) }, uI: { value: 1 } },
      vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
      fragmentShader: 'uniform vec3 uCol; uniform float uI; varying vec2 vUv; void main(){ float d = length(vUv - 0.5) * 2.0; float g = exp(-d*d*3.2); gl_FragColor = vec4(uCol * g * uI, 1.0); }'
    });

    // ---- column shader: soft vertical shaft + falling streaks + CLIMBING PULSE ----
    const colMat = (col) => new THREE.ShaderMaterial({
      transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
      uniforms: {
        uCol: { value: new THREE.Color(col) },
        uI: { value: 0 }, uPh: { value: 0 }, uT: { value: 0 }, uFlash: { value: 0 }
      },
      vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
      fragmentShader: [
        'uniform vec3 uCol; uniform float uI, uPh, uT, uFlash; varying vec2 vUv;',
        'void main(){',
        '  float edge = smoothstep(0.0, 0.30, vUv.x) * smoothstep(1.0, 0.70, vUv.x);',
        '  float vfade = smoothstep(0.0, 0.16, vUv.y) * smoothstep(1.02, 0.72, vUv.y);',
        '  float st = fract(vUv.y * 5.0 + uT * (1.0 + 2.0 * uI));',
        '  float streak = smoothstep(0.0, 0.3, st) * smoothstep(0.7, 0.35, st);',
        '  float base = (0.04 + 0.34 * uI) * edge * vfade * (0.5 + 0.5 * streak);',
        '  float p = exp(-pow((vUv.y - uPh) / 0.07, 2.0)) * min(uI * 3.0, 1.0) * edge;',
        '  vec3 c = uCol * base + uCol * p * 1.15 + vec3(1.0) * p * 0.38 + uCol * uFlash * edge * vfade;',
        '  gl_FragColor = vec4(c, 1.0);',
        '}'
      ].join('\n')
    });

    const GROUND_Y = -0.80;
    // ---- three clouds ----
    const defs = [
      { x: -0.60 * A2, y: 0.58, s: 0.36, col: SG3.warm, deep: SG3.warmDeep, nCol: 3 },
      { x: 0, y: 0.68, s: 0.56, col: SG3.ctr, deep: SG3.vioDeep, nCol: 1 },
      { x: 0.60 * A2, y: 0.58, s: 0.36, col: SG3.vio, deep: SG3.vioDeep, nCol: 3 }
    ];
    T3.clouds = []; T3.cols = [];
    defs.forEach((d, ci) => {
      const grp = new THREE.Group();
      grp.position.set(d.x, d.y, 0);
      sc.add(grp);
      // luminous under-edge (the scrim law: dark mass, one luminous edge)
      const gq = new THREE.Mesh(new THREE.PlaneGeometry(0.9, 0.34), glowMat(d.col));
      gq.position.set(0, -0.20, 0.12); gq.scale.setScalar(d.s * 2.6);
      grp.add(gq);
      T3.clouds.push({ grp, glow: gq, def: d, baseS: d.s, bob: Math.random() * 6 });
      // rain columns
      const offs = d.nCol === 1 ? [0] : [-0.17, 0, 0.17];
      offs.forEach(ox => {
        const w = d.nCol === 1 ? 0.16 : 0.085;
        const top = d.y - 0.14, h = top - GROUND_Y;
        const m = colMat(d.col);
        const q = new THREE.Mesh(new THREE.PlaneGeometry(w, h), m);
        q.position.set(d.x + ox, GROUND_Y + h / 2, -0.1);
        sc.add(q);
        T3.cols.push({ mesh: q, mat: m, cloud: ci, x: d.x + ox, topY: top });
      });
    });

    // dark cloud masses from the GLBs (fallback: dark blobs)
    const dark = new THREE.MeshBasicMaterial({ color: SG3.cloudDark });
    const addFallback = (c) => {
      const g2 = new THREE.Group();
      [[0, 0, 0.30], [-0.26, -0.05, 0.20], [0.26, -0.04, 0.22], [0.1, 0.12, 0.18]].forEach(b => {
        const m = new THREE.Mesh(new THREE.SphereGeometry(b[2], 7, 5), dark);
        m.position.set(b[0], b[1], 0); g2.add(m);
      });
      g2.scale.setScalar(c.baseS * 1.4); c.grp.add(g2); c.mass = g2;
    };
    if (typeof THREE.GLTFLoader === 'function') {
      const loader = new THREE.GLTFLoader();
      T3.clouds.forEach((c, i) => {
        try {
          const bin = Uint8Array.from(atob(SG3_CLOUDS[i]), ch => ch.charCodeAt(0)).buffer;
          loader.parse(bin, '', gl2 => {
            try {
              const m = gl2.scene;
              m.updateMatrixWorld(true);
              const bb = new THREE.Box3().setFromObject(m);
              const size = bb.getSize(new THREE.Vector3());
              const c0 = bb.getCenter(new THREE.Vector3());
              const f = 1.15 / Math.max(size.x, size.y, size.z, 0.001);
              m.traverse(o => { if (o.isMesh) o.material = dark; });
              const wrap = new THREE.Group();
              m.position.sub(c0);
              wrap.add(m);
              wrap.scale.setScalar(c.baseS * f * 1.05);
              c.grp.add(wrap); c.mass = wrap; // animate the WRAP, never the centered child
            } catch (e) { addFallback(c); }
          }, () => addFallback(c));
        } catch (e) { addFallback(c); }
      });
    } else T3.clouds.forEach(addFallback);

    // moisture strips on the ground (3 regions)
    T3.moistQ = defs.map(d => {
      const m = new THREE.MeshBasicMaterial({ color: d.col, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false });
      const q = new THREE.Mesh(new THREE.PlaneGeometry(0.72 * (d.nCol === 1 ? 0.8 : 1), 0.05), m);
      q.position.set(d.x, GROUND_Y, 0.1);
      sc.add(q); return m;
    });
    // ground line
    const gl = new THREE.Mesh(new THREE.PlaneGeometry(2 * A2, 0.012), new THREE.MeshBasicMaterial({ color: 0x2a2348 }));
    gl.position.y = GROUND_Y; sc.add(gl);

    // ---- jelly plant factory (procedural, flat kit) ----
    T3.mkPlant = (x, region) => {
      const col = defs[region].col;
      const g2 = new THREE.Group();
      const stalk = new THREE.Mesh(
        new THREE.CylinderGeometry(0.006, 0.016, 0.30, 6),
        new THREE.MeshBasicMaterial({ color: SG3.cloudDark })
      );
      stalk.position.y = 0.15; g2.add(stalk);
      const bellM = new THREE.MeshBasicMaterial({ color: col, transparent: true, opacity: 0.42, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
      const bell = new THREE.Mesh(new THREE.SphereGeometry(0.085, 8, 5, 0, Math.PI * 2, 0, Math.PI / 2), bellM);
      bell.position.y = 0.30; g2.add(bell);
      const core = new THREE.Mesh(new THREE.PlaneGeometry(0.22, 0.22), glowMat(col));
      core.position.y = 0.30; g2.add(core);
      for (let i = 0; i < 3; i++) {
        const fr = new THREE.Mesh(new THREE.PlaneGeometry(0.016, 0.11), bellM);
        fr.position.set((i - 1) * 0.035, 0.24, 0.01);
        g2.add(fr);
      }
      g2.position.set(x, GROUND_Y, 0.2);
      g2.scale.setScalar(0.001);
      sc.add(g2);
      return { grp: g2, bellM, core, region, x, born: 0, life: 1, pulse: 0, sway: Math.random() * 6 };
    };
  },
  step(P, dt, t, inp) {
    const s = P.state;
    if (s.noGL) return;
    const live = (chan.L.mode === 'live' || chan.R.mode === 'live') ? 1 : 0;
    s.pres += (live - s.pres) * Math.min(1, dt * 1.5);
    const tL = clamp(inp.L), tR = clamp(inp.R);
    s.vel = s.vel * Math.max(0, 1 - dt * 2.2) + (Math.abs(tL - s.pL) + Math.abs(tR - s.pR)) * 6;
    s.pL = tL; s.pR = tR;
    s.eL += (tL - s.eL) * Math.min(1, dt * 28);
    s.eR += (tR - s.eR) * Math.min(1, dt * 28);
    if (s.pres < 0.12) { s.idleT += dt; } else s.idleT = 0;

    // BOTH HANDS HIGH = charge the thunder cloud; else each hand rains its side
    s.charging = s.eL > 0.55 && s.eR > 0.55 && s.pres > 0.2;
    if (s.charging && s.strikeCool <= 0) {
      s.charge = Math.min(1, s.charge + dt * 0.30 * (s.eL + s.eR - 1.0));
      if (s.charge >= 1 && !s.strikePending) s.strikePending = true;
    } else if (!s.charging) {
      s.charge = Math.max(0, s.charge - dt * 0.5);
    }
    s.strikeCool = Math.max(0, s.strikeCool - dt);
    const div = 1 - s.charge * 0.65; // charging diverts the rain
    s.rainL = s.eL * s.pres * div * (s.charging ? 0.4 : 1);
    s.rainR = s.eR * s.pres * div * (s.charging ? 0.4 : 1);

    // moisture field — rain feeds it, strikes SOAK the center, slow decay
    s.moist[0] = Math.min(1.35, s.moist[0] + s.rainL * dt * 0.115);
    s.moist[2] = Math.min(1.35, s.moist[2] + s.rainR * dt * 0.115);
    s.moist[1] = Math.min(1.35, s.moist[1] + s.charge * dt * 0.035);
    for (let i = 0; i < 3; i++) s.moist[i] = Math.max(0, s.moist[i] - dt * 0.006);

    // sprout: threshold per region, max 2 plants each, 6 total, on the BAR (audio commits)
    for (let rg = 0; rg < 3; rg++) {
      const inRegion = s.plants.filter(p => p.region === rg && p.life > 0).length;
      if (s.moist[rg] >= 1 && inRegion < 2 && s.plants.filter(p => p.life > 0).length < 6) {
        s.moist[rg] = 0.35;
        s.sproutReq = s.sproutReq || [];
        s.sproutReq.push(rg);
      }
    }

    // strike fires when audio scheduled it and its moment arrives
    if (s.strikeAt && typeof AE !== 'undefined' && AE.ctx && AE.t() >= s.strikeAt) {
      s.strikeAt = 0;
      s.flashA = 1;
      s.boltT = 0.38;
      s.bolt = null; // regenerate in draw at current size
      s.moist[1] = Math.min(1.35, s.moist[1] + 0.55);
      s.pulse = 1;
    }
    s.flashA = Math.max(0, s.flashA - dt * 2.6);
    s.boltT = Math.max(0, s.boltT - dt);
    s.landL = Math.max(0, s.landL - dt * 5);
    s.landR = Math.max(0, s.landR - dt * 5);

    // plants age + sway
    for (const p of s.plants) {
      p.born = Math.min(1, p.born + dt * 2.2);
      p.pulse = Math.max(0, p.pulse - dt * 3.2);
      if (s.idleT > 40) p.life = Math.max(0, p.life - dt * 0.1); // long abandon wilts the garden
    }
  },
  draw(P, g, w, h, t, inp) {
    const s = P.state;
    if (s.noGL || !P._three) {
      g.fillStyle = '#070512'; g.fillRect(0, 0, w, h);
      g.fillStyle = 'rgba(180,170,220,0.75)'; g.font = `${Math.max(10, h * 0.03)}px ui-monospace,monospace`;
      g.textAlign = 'center';
      g.fillText('STORM GARDEN V3 · THE THREE-CLOUD BAND', w / 2, h / 2 - 12);
      g.fillText('open on the hosted site (WebGL)', w / 2, h / 2 + 14);
      g.textAlign = 'left';
      return;
    }
    const T3 = P._three, A2 = T3.A;
    const GROUND_Y = -0.80;
    const beats = (typeof T !== 'undefined' && T.running) ? T.beats() : t * 1.4;

    // clouds: drift, swell (thunder cloud swells with charge)
    T3.clouds.forEach((c, ci) => {
      c.grp.position.y = c.def.y + Math.sin(t * 0.3 + c.bob) * 0.012;
      c.grp.position.x = c.def.x + Math.sin(t * 0.11 + c.bob * 2.1) * 0.02;
      const swell = ci === 1 ? 1 + s.charge * 0.30 + s.flashA * 0.1 : 1 + (ci === 0 ? s.rainL : s.rainR) * 0.08;
      if (c.mass) c.mass.scale.setScalar(c.baseS * 1.05 * swell * (c.userF || 1));
      const e = ci === 0 ? s.rainL : ci === 2 ? s.rainR : Math.max(0.12, s.charge);
      c.glow.material.uniforms.uI.value = 0.22 + e * 1.35 + (ci === 1 ? s.flashA * 2.2 : 0);
      c.glow.scale.setScalar(c.baseS * 2.6 * swell);
    });
    // columns: intensity + CLIMBING PULSE (one grid-interval of travel = the visible metronome)
    T3.cols.forEach(c => {
      const u = c.mat.uniforms;
      u.uT.value = t;
      if (c.cloud === 0) { u.uI.value = s.rainL; u.uPh.value = ((beats * 2) % 1); }        // 8ths
      else if (c.cloud === 2) { u.uI.value = s.rainR; u.uPh.value = ((beats * 4) % 1); }   // 16ths
      else { u.uI.value = Math.max(s.charge * 0.9, s.flashA); u.uPh.value = ((beats / 2) % 1); } // half-bars
      u.uFlash.value = c.cloud === 1 ? s.flashA * 0.9 : (c.cloud === 0 ? s.landL * (0.15 + 0.45 * s.rainL) : s.landR * (0.15 + 0.45 * s.rainR));
    });
    // moisture strips
    T3.moistQ.forEach((m, i) => { m.opacity = Math.min(1, s.moist[i]) * 0.42; });
    // plants: grow-in, sway, beat glow, wilt
    for (const p of s.plants) {
      const k = p.born * p.life;
      p.grp.scale.setScalar(Math.max(0.001, k * 1.6 * (1 + p.pulse * 0.1)));
      p.grp.rotation.z = Math.sin(t * 0.7 + p.sway) * 0.07;
      p.bellM.opacity = 0.42 * p.life + p.pulse * 0.3;
      p.core.material.uniforms.uI.value = 0.35 + p.pulse * 1.4;
    }
    T3.renderer.render(T3.scene, T3.cam);
    g.clearRect(0, 0, w, h);
    g.drawImage(T3.renderer.domElement, 0, 0, w, h);

    // ---- 2D overlay: fat rain, bolt, flash, HUD ----
    const ms = Math.max(1, Math.sqrt(areaScale(P)));
    const wx = x => (x / A2 + 1) * 0.5 * w;      // world→px
    const wy = y => (1 - (y + 1) * 0.5) * h;
    // spawn fat rain streaks under raining clouds
    const spawn = (ci, rate, col) => {
      if (rate < 0.06) return;
      const cols = T3.cols.filter(c => c.cloud === ci);
      for (let i = 0; i < Math.ceil(rate * 2.2); i++) {
        if (Math.random() > rate * 0.85) continue;
        const c = cols[(Math.random() * cols.length) | 0];
        s.drops.push({ x: c.x + (Math.random() - 0.5) * 0.09, y: c.topY - Math.random() * 0.2, v: 1.5 + rate, col, w: (2.6 + rate * 2.8) * ms });
      }
    };
    spawn(0, s.rainL, '#ffb277'); spawn(2, s.rainR, '#c5a3ff');
    g.lineCap = 'round';
    for (let i = s.drops.length - 1; i >= 0; i--) {
      const d = s.drops[i];
      d.y -= d.v * 0.016;
      if (d.y <= GROUND_Y) { s.drops.splice(i, 1); continue; }
      g.strokeStyle = d.col; g.globalAlpha = 0.4;
      g.lineWidth = d.w;
      g.beginPath(); g.moveTo(wx(d.x), wy(d.y)); g.lineTo(wx(d.x), wy(d.y + 0.13)); g.stroke();
    }
    g.globalAlpha = 1;
    if (s.drops.length > 260) s.drops.splice(0, s.drops.length - 260);
    // the STRIKE: fat forked bolt + full-frame flood
    if (s.boltT > 0) {
      if (!s.bolt) {
        const pts = [[0, 0.5]]; let x = 0;
        for (let y = 0.5; y > GROUND_Y; y -= 0.13) { x += (Math.random() - 0.5) * 0.22; pts.push([x, y]); }
        pts.push([x, GROUND_Y]);
        const fork = pts.slice(0, 4 + (Math.random() * 3 | 0)).map(p => [...p]);
        let fx = fork[fork.length - 1][0];
        for (let y = fork[fork.length - 1][1]; y > GROUND_Y + 0.3; y -= 0.15) { fx += (Math.random() < 0.5 ? -1 : 1) * 0.12; fork.push([fx, y]); }
        s.bolt = { pts, fork };
      }
      const flick = 0.55 + Math.random() * 0.45;
      const draw = (pts, wGlow, wCore) => {
        g.beginPath(); pts.forEach((p, i) => i ? g.lineTo(wx(p[0]), wy(p[1])) : g.moveTo(wx(p[0]), wy(p[1])));
        g.strokeStyle = 'rgba(160,108,255,' + 0.5 * flick + ')'; g.lineWidth = wGlow * ms; g.stroke();
        g.beginPath(); pts.forEach((p, i) => i ? g.lineTo(wx(p[0]), wy(p[1])) : g.moveTo(wx(p[0]), wy(p[1])));
        g.strokeStyle = 'rgba(245,240,255,' + 0.9 * flick + ')'; g.lineWidth = wCore * ms; g.stroke();
      };
      draw(s.bolt.pts, 26, 9);
      draw(s.bolt.fork, 16, 5);
    }
    if (s.flashA > 0.01) {
      g.fillStyle = 'rgba(233,224,255,' + (s.flashA * 0.8) + ')';
      g.fillRect(0, 0, w, h);
    }
    // HUD
    g.fillStyle = 'rgba(200,190,215,0.75)'; g.font = `${Math.round(10 * ms)}px ui-monospace,monospace`;
    const alive = s.plants.filter(p => p.life > 0.05).length;
    g.fillText('RAIN L ' + Math.round(s.rainL * 100) + '% / R ' + Math.round(s.rainR * 100) + '%  ·  CHARGE ' + Math.round(s.charge * 100) + '%  ·  JELLIES ' + alive + '/6  ·  ' + (H.label || '') + (s.pres < 0.3 ? '  ·  SLEEPING' : ''), 10, h - 10);
  },
  audio(A, P) {
    const v = A.voice();
    // DRONE: sub on the chord root + two soft triangle bed voices + plant voices
    const sub = v.osc('sine', H.chordTone(0, -1));
    const subG = v.g(0.030); sub.connect(subG); subG.connect(v.group);
    const bed = [1, 3].map(i => {
      const o = v.osc('triangle', H.chordTone(i, 0));
      const gg = v.g(0.006); o.connect(gg); gg.connect(v.group);
      return { o, i };
    });
    const plantV = [];
    for (let i = 0; i < 6; i++) {
      const o = v.osc('triangle', H.chordTone(2 + i, i < 3 ? 0 : 1));
      const gg = v.g(0.0001);
      const pan = A.ctx.createStereoPanner ? A.ctx.createStereoPanner() : null;
      if (pan) { o.connect(gg); gg.connect(pan); pan.connect(v.group); }
      else { o.connect(gg); gg.connect(v.group); }
      plantV.push({ o, gg, pan, idx: 2 + i, oct: i < 3 ? 0 : 1 });
    }
    // charge rumble: looped noise through a lowpass that opens with the hold
    const nsrc = A.ctx.createBufferSource(); nsrc.buffer = A.noiseBuf(); nsrc.loop = true;
    const nLP = A.ctx.createBiquadFilter(); nLP.type = 'lowpass'; nLP.frequency.value = 90; nLP.Q.value = 0.6;
    const nG = A.ctx.createGain(); nG.gain.value = 0.0001;
    nsrc.connect(nLP); nLP.connect(nG); nG.connect(v.group); nsrc.start();
    if (A.revIn) { const s2 = A.ctx.createGain(); s2.gain.value = 0.5; v.group.connect(s2); s2.connect(A.revIn); }
    H.onChord(() => {
      A.set(sub.frequency, H.chordTone(0, -1), 0.25);
      bed.forEach(b => A.set(b.o.frequency, H.chordTone(b.i, 0), 0.2));
      plantV.forEach(p => A.set(p.o.frequency, H.chordTone(p.idx, p.oct), 0.2));
    });
    v.fadeIn(1, 1.4);
    let nextT = T.next(0.25), step16 = 0, ladL = 0, ladR = 0;
    return {
      tick(inp) {
        const s = P.state;
        // drone follows the garden: each grown plant is a voice
        s.plants.forEach((p, i) => {
          if (i < 6) {
            A.set(plantV[i].gg.gain, 0.0072 * p.life * p.born * (0.4 + 0.6 * s.pres), 0.4);
            if (plantV[i].pan) plantV[i].pan.pan.value = clamp(p.x / 1.4, -1, 1);
          }
        });
        // charge tension
        A.set(nG.gain, s.charge * 0.055 + s.rainL * 0.004 + s.rainR * 0.004, 0.2);
        A.set(nLP.frequency, 90 + s.charge * 1500 + Math.min(0.5, s.vel) * 200, 0.25);
        MOut.expr('arp', s.rainL); MOut.expr('bells', s.rainR);
        MOut.expr('texture', s.charge); MOut.expr('pad', s.plants.filter(p => p.life > 0.05).length / 6);
        const horizon = A.t() + 0.15;
        while (nextT < horizon) {
          const st = step16 % 16;
          const tt = nextT;
          // EARTH cloud: warm plucks on 8ths — the pulse you watched climbing lands NOW
          if (st % 2 === 0 && s.rainL > 0.06) {
            const freq = H.chordTone(ladL % 4, 0);
            A.pluck2(freq, { at: tt, vol: 0.022 + s.rainL * 0.05, pan: -0.55, rev: 0.35, dur: 0.5 });
            MOut.evNote('arp', freq, 0.08 + s.rainL * 0.1, tt, 0.4);
            s.landL = 1; ladL++;
          }
          // SKY cloud: violet bells on 16ths (pattern-skipped for air)
          if (st % 4 !== 3 && s.rainR > 0.06) {
            const freq = H.chordTone(2 + (ladR % 4), 1);
            A.bell(freq, { at: tt, vol: 0.012 + s.rainR * 0.030, pan: 0.55, dur: 1.1, rev: 0.55 });
            MOut.evNote('bells', freq, 0.06 + s.rainR * 0.09, tt, 0.9);
            s.landR = 1; ladR++;
          }
          // THUNDER: strike commits on the half-bar
          if (st % 8 === 0 && s.strikePending && s.strikeCool <= 0) {
            s.strikePending = false; s.charge = 0; s.strikeCool = 2.2;
            s.strikeAt = tt;
            A.kick(tt, 0.5);
            const drop = A.ctx.createOscillator(); drop.type = 'sine';
            drop.frequency.setValueAtTime(88, tt);
            drop.frequency.exponentialRampToValueAtTime(27, tt + 0.9);
            const dg = A.ctx.createGain();
            dg.gain.setValueAtTime(0.24, tt);
            dg.gain.exponentialRampToValueAtTime(0.0001, tt + 1.1);
            drop.connect(dg); dg.connect(A.master); drop.start(tt); drop.stop(tt + 1.2);
            const th = A.ctx.createBufferSource(); th.buffer = A.noiseBuf();
            const tf = A.ctx.createBiquadFilter(); tf.type = 'lowpass'; tf.frequency.value = 420;
            const tg = A.ctx.createGain();
            tg.gain.setValueAtTime(0.0001, tt);
            tg.gain.linearRampToValueAtTime(0.30, tt + 0.05);
            tg.gain.exponentialRampToValueAtTime(0.0001, tt + 2.4);
            th.connect(tf); tf.connect(tg); tg.connect(A.master);
            if (A.revIn) { const s3 = A.ctx.createGain(); s3.gain.value = 0.8; tg.connect(s3); s3.connect(A.revIn); }
            th.start(tt); th.stop(tt + 2.5);
            MOut.evDrum(36, 0.9, tt);
            MOut.evNote('texture', H.rootFreq(-2), 0.9, tt, 2.5);
          }
          // SPROUTS commit on the bar, rolled low→high
          if (st === 0 && s.sproutReq && s.sproutReq.length) {
            const rg = s.sproutReq.shift();
            const T3 = P._three;
            if (T3 && T3.mkPlant) {
              const cx = [-0.6 * T3.A, 0, 0.6 * T3.A][rg];
              const px = cx + (Math.random() - 0.5) * 0.5;
              const p = T3.mkPlant(px, rg);
              p.pulse = 1;
              s.plants.push(p);
              [0, 1, 2].forEach(ri => {
                const freq = H.chordTone(2 + ri * 2, ri === 2 ? 1 : 0);
                A.bell(freq, { at: tt + ri * 0.08, vol: 0.042, dur: 2.6, rev: 0.75, pan: clamp(px / 1.4, -1, 1) * 0.6 });
                MOut.evNote('pad', freq, 0.1, tt + ri * 0.08, 2.2);
              });
            }
          }
          step16++; nextT += T.beat * 0.25;
        }
        if (nextT < A.t()) nextT = T.next(0.25);
      },
      stop() { try { nsrc.stop(); } catch (e) {} v.kill(); }
    };
  }
});
})();
